from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
root=Path('documents/matters')
out=Path('engagement_text.txt')
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
files=[]
for p in root.glob('*/*/*.docx'):
    if 'engagement' in p.parent.name.lower() or 'administrat' in p.parent.name.lower() or 'opening' in p.name.lower() or 'staffing' in p.name.lower() or 'conflict' in p.name.lower():
        files.append(p)
with out.open('w',encoding='utf-8') as fh:
    for p in sorted(files):
        fh.write(f'===== {p} =====\n')
        try:
            with ZipFile(p) as z:
                xml=z.read('word/document.xml')
            rootxml=ET.fromstring(xml)
            for para in rootxml.findall('.//w:p',ns):
                texts=[t.text or '' for t in para.findall('.//w:t',ns)]
                if texts: fh.write(''.join(texts)+'\n')
        except Exception as e:
            fh.write(f'[ERROR {e}]\n')
        fh.write('\n')
print(f'processed {len(files)} files -> {out}')
PY","description":"Extract engagement metadata text","timeoutMs":120000}

