from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
import re
root=Path('documents/matters')
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
terms=re.compile(r'(?i)LPAC|limited partner advisory committee|LP advisory committee|advisory committee|LPA|limited partnership agreement|signed|executed')
for mdir in sorted(root.iterdir()):
    if not mdir.is_dir(): continue
    hits=[]
    for p in mdir.rglob('*.docx'):
        try:
            with ZipFile(p) as z: xml=z.read('word/document.xml')
            rt=ET.fromstring(xml)
            paras=[]
            for para in rt.findall('.//w:p',ns):
                s=''.join((t.text or '') for t in para.findall('.//w:t',ns))
                if s: paras.append(s)
            txt='\n'.join(paras)
        except: continue
        if re.search(r'(?i)LPAC|limited partner advisory committee|LP advisory committee',txt):
            tl=[x.strip() for x in paras if re.search(r'(?i)LPAC|limited partner advisory committee|LP advisory committee',x)]
            sig=[x.strip() for x in paras if re.search(r'(?i)signature|executed|signed|date:',x)]
            hits.append((str(p.relative_to(mdir)),tl[:8],sig[:8]))
    if hits:
        print(f'===== {mdir.name} ({len(hits)} docs) =====')
        for fn,tl,sig in hits:
            print('FILE:',fn)
            for x in tl: print('LP:',x[:400])
            for x in sig: print('SIG:',x[:250])
PY","description":"Index LPAC evidence by matter","timeoutMs":120000}

